import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Lodestone API & MCP — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"api-01-overview-and-concepts.md","filePath":"api-01-overview-and-concepts.md"}'),r={name:"api-01-overview-and-concepts.md"};function i(n,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="lodestone-api-mcp-—-overview-concepts" tabindex="-1">Lodestone API &amp; MCP — Overview &amp; Concepts <a class="header-anchor" href="#lodestone-api-mcp-—-overview-concepts" aria-label="Permalink to &quot;Lodestone API &amp; MCP — Overview &amp; Concepts&quot;">​</a></h1><p><em>What it is, what it enables, and how it fits into your workflow</em></p><hr><h2 id="what-is-the-lodestone-api" tabindex="-1">What Is the Lodestone API? <a class="header-anchor" href="#what-is-the-lodestone-api" aria-label="Permalink to &quot;What Is the Lodestone API?&quot;">​</a></h2><p>Lodestone exposes a REST API that gives external tools programmatic access to your workspace data. With the API, you can read and write Features, Roadmaps, Releases, Strategies, and more — using any tool or service that can make HTTP requests.</p><p>The API uses <strong>API keys</strong> for authentication. You generate a key inside Lodestone, copy it once, and then provide it to the external tool or service that needs access.</p><hr><h2 id="what-the-api-enables" tabindex="-1">What the API Enables <a class="header-anchor" href="#what-the-api-enables" aria-label="Permalink to &quot;What the API Enables&quot;">​</a></h2><p>The most powerful use case for the Lodestone API is connecting your workspace to an AI assistant — a custom ChatGPT, Claude, or other LLM configuration that can read and act on your Lodestone data using natural language.</p><p>For example, you could build or configure a custom AI assistant that can:</p><ul><li>Retrieve your feature backlog and summarize it</li><li>Create a new Feature from a customer conversation</li><li>Update a Feature&#39;s status based on a message you send</li><li>List what&#39;s in a Release and draft a status update</li><li>Pull your Roadmap structure and prepare talking points for a meeting</li></ul><p>Because the Lodestone API follows the OpenAPI standard, it is compatible with the custom tool/action frameworks in ChatGPT (Custom GPTs), Claude Projects, and similar LLM environments. You can point your AI assistant at the Lodestone API and give it read and write access to your product data — turning it into a Lodestone-aware productivity tool without any code.</p><hr><h2 id="what-the-api-covers" tabindex="-1">What the API Covers <a class="header-anchor" href="#what-the-api-covers" aria-label="Permalink to &quot;What the API Covers&quot;">​</a></h2><p>The API is organized around the same objects you work with in Lodestone:</p><table tabindex="0"><thead><tr><th>Resource</th><th>What you can do</th></tr></thead><tbody><tr><td>Features</td><td>List, read, create, update, manage tags</td></tr><tr><td>Roadmaps (Projects)</td><td>List, read, create, update; add and remove Features</td></tr><tr><td>Releases</td><td>List, read, create, update; manage release plan items and release notes</td></tr><tr><td>Strategies</td><td>List, read, create, update</td></tr><tr><td>Organizations</td><td>Read org details, list members, manage status stages</td></tr><tr><td>Bento Grids</td><td>List, read, create, update</td></tr></tbody></table><p>All endpoints are under <code>/api/v1/</code>. An OpenAPI specification is available at <code>/api/v1/openapi</code>, which you can import into AI tools, API clients, or any service that accepts an OpenAPI schema.</p><hr><h2 id="scopes-and-permissions" tabindex="-1">Scopes and Permissions <a class="header-anchor" href="#scopes-and-permissions" aria-label="Permalink to &quot;Scopes and Permissions&quot;">​</a></h2><p>When you generate an API key, you choose which scopes it is authorized for. Scopes control what the key can read or write:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Access</th></tr></thead><tbody><tr><td><code>features:read</code></td><td>Read Features and their details</td></tr><tr><td><code>features:write</code></td><td>Create and update Features</td></tr><tr><td><code>projects:read</code></td><td>Read Roadmaps</td></tr><tr><td><code>projects:write</code></td><td>Create and update Roadmaps</td></tr><tr><td><code>releases:read</code></td><td>Read Releases</td></tr><tr><td><code>releases:write</code></td><td>Create and update Releases</td></tr><tr><td><code>strategies:read</code></td><td>Read Strategies</td></tr><tr><td><code>strategies:write</code></td><td>Create and update Strategies</td></tr><tr><td><code>bento-grids:read</code></td><td>Read Bento Grids</td></tr><tr><td><code>bento-grids:write</code></td><td>Create and update Bento Grids</td></tr><tr><td><code>settings:read</code></td><td>Read org settings</td></tr><tr><td><code>settings:write</code></td><td>Update org settings</td></tr><tr><td><code>*</code></td><td>Full access to all scopes</td></tr></tbody></table><p>Choose the minimum scopes needed for the tool you&#39;re connecting. A read-only AI assistant for summarizing your backlog only needs <code>:read</code> scopes. An assistant that can create Features needs <code>features:write</code> as well.</p><hr><h2 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h2><p>In addition to the REST API, Lodestone exposes an <strong>MCP (Model Context Protocol) server</strong> that allows AI agents and LLM environments to connect to Lodestone using the emerging MCP standard.</p><p>The MCP server URL for your workspace is shown in <strong>Settings &gt; API &amp; MCP</strong>. You can connect MCP-compatible AI tools (such as Claude Desktop or Claude Code) directly to this URL to give them native Lodestone access — querying, creating, and updating objects using natural language without writing custom API code.</p><p>MCP connectivity is authenticated using the same API keys used for REST API access.</p><hr><h2 id="how-api-keys-work" tabindex="-1">How API Keys Work <a class="header-anchor" href="#how-api-keys-work" aria-label="Permalink to &quot;How API Keys Work&quot;">​</a></h2><ul><li>Each key is associated with a specific organization in Lodestone</li><li>The full key value is shown <strong>only once</strong> — at the moment of creation. Copy it immediately.</li><li>Keys do not expire by default, but can be revoked at any time from Settings &gt; API &amp; MCP</li><li>Only one active key is shown in the main integrations panel at a time, but multiple keys can exist per organization</li></ul><blockquote><p><strong>Security note:</strong> Treat your API key like a password. Do not share it publicly, embed it in client-side code, or commit it to a repository. If a key is compromised, revoke it immediately and generate a new one.</p></blockquote><hr><h2 id="how-requests-are-authenticated" tabindex="-1">How Requests Are Authenticated <a class="header-anchor" href="#how-requests-are-authenticated" aria-label="Permalink to &quot;How Requests Are Authenticated&quot;">​</a></h2><p>Include the API key in the <code>Authorization</code> header of every request:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer YOUR_API_KEY</span></span></code></pre></div><p>Requests without a valid key return a <code>401 Unauthorized</code> response. Requests with a key that lacks the required scope return a <code>403 Forbidden</code> response.</p><hr><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><p>The API enforces rate limits to ensure fair usage. If you exceed the limit, requests return a <code>429 Too Many Requests</code> response. Implement appropriate retry logic with exponential backoff in any integration that makes high-frequency requests.</p><hr><h2 id="how-the-api-relates-to-the-rest-of-lodestone" tabindex="-1">How the API Relates to the Rest of Lodestone <a class="header-anchor" href="#how-the-api-relates-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How the API Relates to the Rest of Lodestone&quot;">​</a></h2><p>The API is a read/write mirror of the Lodestone interface. Everything the API can do, you can also do manually through the Lodestone UI. The API adds:</p><ul><li><strong>Automation</strong> — trigger Lodestone actions from external systems or scheduled jobs</li><li><strong>Integration</strong> — sync Lodestone data with other tools</li><li><strong>AI access</strong> — give an LLM assistant the ability to read and act on your product data</li></ul><p>Changes made via the API appear in Lodestone immediately and are indistinguishable from changes made through the interface.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for generating API keys and connecting an AI assistant to Lodestone.</em></p>',46)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
